        for i in range(self.dim):
            result += 0.15 * np.sin(20.0 * x[i] + 0.5 * np.sin(5.0 * x[i]))

        # Boundary attraction and repulsion terms
        for i in range(self.dim):
            if abs(x[i]) < 1.0:
                result += 0.3 * (1.0 - abs(x[i]))**2
            else:
                result += 0.2 * (abs(x[i]) - 4.0)**2

